package com.ashrafwebdev.sikkanam.learn

/**
 * One item to learn. Every item has the original Arabic, a transliteration in Tamil and in English,
 * and the meaning in Tamil and English. Entries with no Arabic (for example, a step description)
 * leave those fields blank.
 *
 * The prayer rules in this file follow the Hanafi school, with a separate Shafi'i section for the
 * differences. NOTE: All content must be checked by a qualified teacher before it is used.
 * The Tamil transliterations and Tamil meanings are unreviewed.
 */
data class LearnItem(
    val id: String,
    val title: String,
    val arabic: String,
    val tamilTransliteration: String,
    val englishTransliteration: String,
    val meaningTamil: String,
    val meaningEnglish: String,
)

data class LearnCategory(val title: String, val items: List<LearnItem>)

