                    englishTransliteration = "Bismika Allahumma amootu wa ahyaa.",
                    meaningTamil = "அல்லாஹ்வே! உன் பெயரால் நான் இறக்கிறேன், வாழ்கிறேன்.",
                    meaningEnglish = "In Your name, O Allah, I die and I live.",
