                    arabic = "الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ",
                    tamilTransliteration = "அல்ஹம்து லில்லாஹில்லதீ அஹ்யானா பஃது மா அமாதனா வ இலைஹின் நுஷூர்.",
                    englishTransliteration = "Alhamdu lillahil-ladhee ahyaanaa ba'da maa amaatanaa wa ilayhin-nushoor.",
                    meaningTamil = "எங்களை மரணிக்கச் செய்த பின் எங்களை உயிர்ப்பித்த அல்லாஹ்வுக்கே எல்லாப் புகழும்; அவனிடமே மீண்டெழுதல்.",
                    meaningEnglish = "All praise is for Allah, who gave us life after He had caused us to die, and to Him is the resurrection.",
                ),
                LearnItem(
                    id = "dua_leave_home", title = "When leaving home",
                    arabic = "بِسْمِ اللَّهِ تَوَكَّلْتُ عَلَى اللَّهِ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ",
                    tamilTransliteration = "பிஸ்மில்லாஹி தவக்கல்து அலல்லாஹி வலா ஹவ்ல வலா குவ்வத்த இல்லா பில்லாஹ்.",
                    englishTransliteration = "Bismillahi tawakkaltu 'alallahi wa laa hawla wa laa quwwata illaa billah.",
                    meaningTamil = "அல்லாஹ்வின் பெயரால். அல்லாஹ்வையே நம்பினேன். அல்லாஹ்வின் உதவியின்றி எந்த சக்தியும் பலமும் இல்லை.",
                    meaningEnglish = "In the name of Allah. I place my trust in Allah. There is no power and no strength except with Allah.",
                ),
                LearnItem(
                    id = "dua_travel", title = "Travel dua",
                    arabic = "سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ",
                    tamilTransliteration = "சுப்ஹானல்லதீ சக்கர லனா ஹாதா வ மா குன்ன லஹு முக்ரினீன். வ இன்னா இலா ரப்பினா லமுன்கலிபூன்.",
                    englishTransliteration = "Subhaanal-ladhee sakhkhara lanaa haadhaa wa maa kunnaa lahu muqrineen. Wa innaa ilaa Rabbinaa lamunqaliboon.",
                    meaningTamil = "இதை எங்களுக்கு வசப்படுத்தித் தந்தவன் தூயவன். இதை எங்களால் வசப்படுத்த முடியாது. நிச்சயமாக நாங்கள் எங்கள் இறைவனிடமே திரும்பிச் செல்பவர்கள்.",
                    meaningEnglish = "Glory be to Him who has subjected this to us, and we could not have done it ourselves. And to our Lord we will surely return.",
                ),
                LearnItem(
                    id = "dua_istighfar", title = "Seeking forgiveness",
                    arabic = "أَسْتَغْفِرُ اللَّهَ",
                    tamilTransliteration = "அஸ்தக்ஃபிருல்லாஹ்.",
                    englishTransliteration = "Astaghfirullah.",
                    meaningTamil = "அல்லாஹ்விடம் மன்னிப்புக் கோருகிறேன்.",
                    meaningEnglish = "I seek forgiveness from Allah.",
                ),
                LearnItem(
                    id = "dua_enter_masjid", title = "Entering the masjid",
                    arabic = "اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ",
                    tamilTransliteration = "அல்லாஹும்மஃப்தஹ் லீ அப்வாப ரஹ்மதிக.",
                    englishTransliteration = "Allahumma iftah lee abwaaba rahmatik.",
                    meaningTamil = "இறைவா! உன் அருளின் வாசல்களை எனக்குத் திறந்து விடுவாயாக. (வலது காலை வைத்து உள்ளே நுழையும்போது, பிஸ்மில்லாஹ் சொல்லவும்; பின்னர் நபி (ஸல்) மீது ஸலவாத் சொல்லவும்.)",
                    meaningEnglish = "O Allah, open for me the doors of Your mercy. (Enter with the right foot, say 'Bismillah', and send blessings on the Prophet.)",
                ),
                LearnItem(
                    id = "dua_leave_masjid", title = "Leaving the masjid",
                    arabic = "اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ",
                    tamilTransliteration = "அல்லாஹும்ம இன்னீ அஸ்அலுக்க மின் ஃபள்லிக்க.",
                    englishTransliteration = "Allahumma innee as'aluka min fadlik.",
                    meaningTamil = "இறைவா! உன் அருளில் இருந்து உன்னிடம் கேட்கிறேன். (இடது காலை வைத்து வெளியேறும்போது, நபி (ஸல்) மீது ஸலவாத் சொல்லவும்.)",
                    meaningEnglish = "O Allah, I ask You of Your bounty. (Leave with the left foot, and send blessings on the Prophet.)",
                ),
                LearnItem(
                    id = "niyyat_itikaf", title = "Niyyah for I'tikaf (staying in the masjid)",
                    arabic = "نَوَيْتُ سُنَّةَ الِاعْتِكَافِ لِلَّهِ تَعَالَى",
                    tamilTransliteration = "நவைது சுன்னதல் இஃதிகாஃபி லில்லாஹி தஆலா.",
                    englishTransliteration = "Nawaytu sunnatal-i'tikaafi lillahi ta'aalaa.",
                    meaningTamil = "அல்லாஹ் தஆலாவுக்காக, இஃதிகாஃப் (பள்ளியில் தங்கியிருத்தல்) என்ற சுன்னத்தை நிய்யத் செய்தேன். (நிய்யத் மனதில் இருக்க வேண்டும்; சொல்வது கட்டாயமில்லை.)",
                    meaningEnglish = "I intend the sunnah of i'tikaf for the sake of Allah, the Exalted. (The intention is made in the heart; saying it aloud is not required.)",
                ),
                LearnItem(
                    id = "dua_istikhara", title = "Istikhara (asking Allah to choose)",
                    arabic = "اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ، فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ، وَتَعْلَمُ وَلَا أَعْلَمُ، وَأَنْتَ عَلَّامُ الْغُيُوبِ. اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي فَاقْدُرْهُ لِي وَيَسِّرْهُ لِي ثُمَّ بَارِكْ لِي فِيهِ، وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ، وَاقْدُرْ لِيَ الْخَيْرَ حَيْثُ كَانَ ثُمَّ أَرْضِنِي بِهِ",
                    tamilTransliteration = "அல்லாஹும்ம இன்னீ அஸ்தகீருக்க பி இல்மிக்க, வ அஸ்தக்திருக்க பி குத்ரதிக்க, வ அஸ்அலுக்க மின் ஃபள்லிகல் அளீம். ஃபா இன்னக்க தக்திரு வலா அக்திரு, வ தஃலமு வலா அஃலமு, வ அன்த்த அல்லாமுல் குயூப். அல்லாஹும்ம இன் குன்த தஃலமு அன்ன ஹாதல் அம்ர கைருன் லீ ஃபீ தீனீ வ மஆஷீ வ ஆகிபதி அம்ரீ ஃபக்திர்ஹு லீ வ யஸ்ஸிர்ஹு லீ தும்ம பாரிக் லீ ஃபீஹ். வ இன் குன்த தஃலமு அன்ன ஹாதல் அம்ர ஷர்ருன் லீ ஃபீ தீனீ வ மஆஷீ வ ஆகிபதி அம்ரீ ஃபஸ்ரிஃப்ஹு அன்னீ வஸ்ரிஃப்னீ அன்ஹு, வக்திர் லியல் கைர ஹைது கான், தும்ம அர்ழினீ பிஹ்.",
                    englishTransliteration = "Allahumma innee astakheeruka bi-'ilmika, wa astaqdiruka bi-qudratika, wa as'aluka min fadlikal-'adheem. Fa innaka taqdiru wa laa aqdiru, wa ta'lamu wa laa a'lamu, wa anta 'allaamul-ghuyoob. Allahumma in kunta ta'lamu anna haadhal-amra khayrun lee fee deenee wa ma'aashee wa 'aaqibati amree, fa-iqdurhu lee wa yassirhu lee thumma baarik lee feeh. Wa in kunta ta'lamu anna haadhal-amra sharrun lee fee deenee wa ma'aashee wa 'aaqibati amree, fa-isrifhu 'annee wasrifnee 'anh, waqdur liyal-khayra haythu kaana thumma ardhinee bih.",
                    meaningTamil = "இறைவா! உன் ஞானத்தின் மூலம் உன்னிடம் நல்லதைத் தேர்வு செய்யக் கேட்கிறேன்; உன் ஆற்றலின் மூலம் ஆற்றல் கேட்கிறேன்; உன் மகத்தான அருளைக் கேட்கிறேன். நீயே ஆற்றல் உடையவன்; நான் ஆற்றல் அற்றவன். நீயே அறிபவன்; நான் அறியாதவன். இந்த காரியம் என் மார்க்கத்திற்கும், வாழ்வாதாரத்திற்கும், என் முடிவுக்கும் நன்மையானது என்று நீ அறிந்தால், அதை எனக்கு விதித்து, எளிதாக்கி, அதில் அருள் புரிவாயாக. தீமையானது என்று அறிந்தால், அதை என்னை விட்டுத் திருப்பி, என்னையும் அதை விட்டுத் திருப்பி விடு; நன்மை எங்கிருந்தாலும் அதை எனக்கு விதித்து, அதில் என்னைத் திருப்தியடையச் செய்வாயாக.",
                    meaningEnglish = "O Allah, I ask You for guidance by Your knowledge, and I ask You for ability by Your power, and I ask You of Your great bounty. You have power and I have none; You know and I do not; and You are the Knower of the unseen. O Allah, if You know this matter is good for me in my religion, my livelihood, and the outcome of my affair, then decree it for me, make it easy for me, and bless me in it. And if You know this matter is bad for me in my religion, my livelihood, and the outcome of my affair, then turn it away from me and turn me away from it, decree for me what is good wherever it may be, and make me content with it.",
                ),
            ),
