        LearnCategory(
            title = "Hanafi: how to pray (steps)",
            items = listOf(
                LearnItem(
                    id = "h_steps", title = "Steps of a Hanafi prayer",
                    arabic = "", tamilTransliteration = "", englishTransliteration = "",
                    meaningTamil = "1) நிய்யத் செய்து கிப்லாவை நோக்கி நிற்கவும். 2) தக்பீர் தஹ்ரீமா: 'அல்லாஹு அக்பர்' என்று கூறி கைகளை காதுகளுக்கு அருகில் உயர்த்தி, பின் வலது கையை இடது கையின் மீது வைத்து, தொப்புளுக்குக் கீழே கட்டவும். 3) சனா ஓதவும். 4) அஊது பிள்ளா, பிஸ்மில்லாஹ் (மெதுவாக), பின் சூரா ஃபாத்திஹா; ஆமீன் (மெதுவாக). 5) ஒரு சூரா அல்லது சில ஆயத்துகள். 6) ருகூஃ: 'சுப்ஹான ரப்பியல் அழீம்' மூன்று முறை. 7) எழுந்து 'சமிஅல்லாஹு லிமன் ஹமிதஹ், ரப்பனா லகல் ஹம்த்'. 8) சுஜூத்: 'சுப்ஹான ரப்பியல் அஃலா' மூன்று முறை. 9) இரண்டு சுஜூதுகளுக்கு இடையில் அமர்தல். 10) இரண்டாம் ரக்அத்திற்குப் பின் அத்தஹிய்யாத், ஸலவாத், துஆ, பின் வலது பக்கமும் இடது பக்கமும் ஸலாம்.",
                    meaningEnglish = "1) Make the intention and stand facing the qibla. 2) Takbir al-ihram: say 'Allahu akbar', raise the hands near the ears, then place the right hand over the left below the navel. 3) Recite Thana. 4) Recite 'A'udhu billah' and 'Bismillah' silently, then Al-Fatiha, and say 'Ameen' silently. 5) Recite a surah or some verses. 6) Bow: say 'Subhana Rabbiyal-'adheem' three times. 7) Rise: 'Sami'allahu liman hamidah, Rabbana lakal-hamd'. 8) Prostrate: 'Subhana Rabbiyal-a'la' three times. 9) Sit briefly between the two prostrations. 10) After the second rakat: tashahhud, salawat, dua, then salam to the right and to the left.",
                ),
            ),
        ),
        LearnCategory(
            title = "Hanafi: funeral prayer (janaza)",
            items = listOf(
                LearnItem(
                    id = "h_janaza_steps", title = "Hanafi janaza: the steps",
                    arabic = "", tamilTransliteration = "", englishTransliteration = "",
                    meaningTamil = "ஹனஃபி ஜனாசா தொழுகை: ருகூஃ, சுஜூத் இல்லை. சூரா ஃபாத்திஹா ஓதுவதில்லை. 1) நிய்யத் (இறந்தவருக்கான ஜனாசா தொழுகை). 2) முதல் தக்பீர்: 'அல்லாஹு அக்பர்' என்று கூறி கைகளை உயர்த்தி, கட்டிக் கொண்டு, சனா ஓதவும். 3) இரண்டாம் தக்பீர்: நபி (ஸல்) மீது ஸலவாத் (இப்ராஹீமிய்யா). 4) மூன்றாம் தக்பீர்: இறந்தவருக்காக துஆ. 5) நான்காம் தக்பீர்: முஸ்லிம்களுக்காக துஆ, பின் வலது, இடது பக்கம் ஸலாம். (கைகளை முதல் தக்பீரில் மட்டும் உயர்த்தவும்.)",
                    meaningEnglish = "Hanafi janaza: no bowing or prostration, and Al-Fatiha is not recited. 1) Intention for the funeral prayer of the deceased. 2) First takbir: say 'Allahu akbar', raise the hands, fold them, and recite Thana. 3) Second takbir: send blessings on the Prophet (Ibrahimiyyah). 4) Third takbir: pray for the deceased. 5) Fourth takbir: pray for all Muslims, then give salam to the right and to the left. (Raise the hands only at the first takbir.)",
                ),
                LearnItem(
                    id = "janaza_thana", title = "Thana (after the first takbir)",
                    arabic = "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، وَتَبَارَكَ اسْمُكَ، وَتَعَالَى جَدُّكَ، وَلَا إِلَٰهَ غَيْرُكَ",
                    tamilTransliteration = "சுப்ஹானக்க அல்லாஹும்ம வ பிஹம்திக்க, வ தபாரக்க இஸ்முக்க, வ தஆலா ஜத்துக்க, வ லா இலாஹ கைருக்க.",
                    englishTransliteration = "Subhaanaka Allahumma wa bihamdika, wa tabaraka ismuka, wa ta'aala jadduka, wa laa ilaha ghayruka.",
                    meaningTamil = "இறைவா! நீ தூயவன்; உனக்கே எல்லாப் புகழும்; உன் பெயர் பாக்கியமானது; உன் மகத்துவம் உயர்ந்தது; உன்னைத் தவிர வணக்கத்திற்குரியவன் இல்லை.",
                    meaningEnglish = "Glory be to You, O Allah, and praise be to You. Blessed is Your name, exalted is Your majesty, and there is no god but You.",
                ),
                LearnItem(
                    id = "janaza_durood", title = "Salawat after the second takbir (Ibrahimiyyah)",
                    arabic = "اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ، وَبَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ",
                    tamilTransliteration = "அல்லாஹும்ம ஸல்லி அலா முஹம்மதின் வ அலா ஆலி முஹம்மத். கமா ஸல்லைத அலா இப்ராஹீம வ அலா ஆலி இப்ராஹீம். இன்னக்க ஹமீதுன் மஜீத். வ பாரிக் அலா முஹம்மதின் வ அலா ஆலி முஹம்மத், கமா பாரக்த அலா இப்ராஹீம வ அலா ஆலி இப்ராஹீம். இன்னக்க ஹமீதுன் மஜீத்.",
                    englishTransliteration = "Allahumma salli 'ala Muhammadin wa 'ala aali Muhammad, kama sallayta 'ala Ibraheema wa 'ala aali Ibraheem, innaka Hameedun Majeed. Wa baarik 'ala Muhammadin wa 'ala aali Muhammad, kama baarakta 'ala Ibraheema wa 'ala aali Ibraheem, innaka Hameedun Majeed.",
                    meaningTamil = "இறைவா! முஹம்மத் (ஸல்) மீதும் அவர்களின் குடும்பத்தார் மீதும் அருள் புரிவாயாக; இப்ராஹீம் (அலை) மீதும் அவர்களின் குடும்பத்தார் மீதும் அருள் புரிந்தது போல். நிச்சயமாக நீ புகழுக்குரியவன், மகத்துவமுடையவன். முஹம்மத் மீதும் அவர்களின் குடும்பத்தார் மீதும் அருள்வளம் தருவாயாக.",
                    meaningEnglish = "O Allah, send blessings upon Muhammad and the family of Muhammad, as You sent blessings upon Ibrahim and the family of Ibrahim. Indeed, You are Praiseworthy and Glorious. And bless Muhammad and the family of Muhammad, as You blessed Ibrahim and the family of Ibrahim. Indeed, You are Praiseworthy and Glorious.",
                ),
                LearnItem(
                    id = "janaza_dua_male", title = "Dua for a deceased man (after the third takbir)",
                    arabic = "اللَّهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ وَعَافِهِ وَاعْفُ عَنْهُ",
                    tamilTransliteration = "அல்லாஹும்மக்ஃபிர் லஹு வர்ஹம்ஹு வ ஆஃபிஹி வஃபு அன்ஹு.",
                    englishTransliteration = "Allahummaghfir lahu warhamhu wa 'aafihi wa'fu 'anhu.",
                    meaningTamil = "இறைவா! இவரை மன்னித்து, இவருக்கு கருணை காட்டி, இவரைப் பாதுகாத்து, இவரது குறைகளை மன்னித்தருள்வாயாக.",
                    meaningEnglish = "O Allah, forgive him, have mercy on him, grant him well-being, and pardon him.",
                ),
                LearnItem(
                    id = "janaza_dua_female", title = "Dua for a deceased woman (after the third takbir)",
                    arabic = "اللَّهُمَّ اغْفِرْ لَهَا وَارْحَمْهَا وَعَافِهَا وَاعْفُ عَنْهَا",
                    tamilTransliteration = "அல்லாஹும்மக்ஃபிர் லஹா வர்ஹம்ஹா வ ஆஃபிஹா வஃபு அன்ஹா.",
                    englishTransliteration = "Allahummaghfir laha warhamha wa 'aafiha wa'fu 'anha.",
                    meaningTamil = "இறைவா! இவரை மன்னித்து, இவருக்கு கருணை காட்டி, இவரைப் பாதுகாத்து, இவரது குறைகளை மன்னித்தருள்வாயாக.",
                    meaningEnglish = "O Allah, forgive her, have mercy on her, grant her well-being, and pardon her.",
                ),
                LearnItem(
                    id = "janaza_dua_all", title = "Dua for all the deceased (after the third takbir, general form)",
                    arabic = "اللَّهُمَّ اغْفِرْ لِحَيِّنَا وَمَيِّتِنَا وَشَاهِدِنَا وَغَائِبِنَا وَصَغِيرِنَا وَكَبِيرِنَا وَذَكَرِنَا وَأُنْثَانَا. اللَّهُمَّ مَنْ أَحْيَيْتَهُ مِنَّا فَأَحْيِهِ عَلَى الْإِسْلَامِ، وَمَنْ تَوَفَّيْتَهُ مِنَّا فَتَوَفَّهُ عَلَى الْإِيمَانِ",
                    tamilTransliteration = "அல்லாஹும்மக்ஃபிர் லிஹய்யினா வ மய்யிதினா, வ ஷாஹிதினா வ ஃகாயிபினா, வ ஸகீரினா வ கபீரினா, வ தகரினா வ உன்தானா. அல்லாஹும்ம மன் அஹ்யய்தஹு மின்னா ஃபஅஹ்யிஹி அலல் இஸ்லாம். வ மன் தவஃப்பய்தஹு மின்னா ஃபதவஃப்பிஹி அலல் ஈமான்.",
                    englishTransliteration = "Allahummaghfir lihayyinaa wa mayyitinaa, wa shaahidinaa wa gha'ibinaa, wa sagheerinaa wa kabeerinaa, wa dhakarinaa wa untaanaa. Allahumma man ahyaytahu minnaa fa-ahyihi 'alal-islaam, wa man tawaffaytahu minnaa fa-tawaffahu 'alal-eemaan.",
                    meaningTamil = "இறைவா! எங்களில் உயிருடன் இருப்பவர்களையும், இறந்தவர்களையும், இங்கு இருப்பவர்களையும், இல்லாதவர்களையும், சிறியவர்களையும், பெரியவர்களையும், ஆண்களையும், பெண்களையும் மன்னிப்பாயாக. எங்களில் எவரை நீ உயிருடன் வைத்தாயோ அவரை இஸ்லாத்தின் மீது வாழச் செய்வாயாக; எங்களில் எவரை நீ மரணிக்கச் செய்தாயோ அவரை ஈமானின் மீது மரணிக்கச் செய்வாயாக.",
                    meaningEnglish = "O Allah, forgive our living and our dead, those present and those absent, our young and our old, our men and our women. O Allah, whoever of us You keep alive, keep alive upon Islam, and whoever of us You cause to die, cause to die upon faith.",
                ),
                LearnItem(
                    id = "janaza_salam", title = "Salam to end the janaza",
                    arabic = "اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ",
                    tamilTransliteration = "அஸ்ஸலாமு அலைக்கும் வ ரஹ்மதுல்லாஹ்.",
                    englishTransliteration = "As-salaamu 'alaykum wa rahmatullah.",
                    meaningTamil = "உங்கள் மீது சாந்தியும் அல்லாஹ்வின் அருளும் உண்டாவதாக. (வலது பக்கம், பின்னர் இடது பக்கம்.)",
                    meaningEnglish = "Peace and the mercy of Allah be upon you. (To the right, then to the left.)",
                ),
            ),
        ),
        LearnCategory(
            title = "Hanafi: Friday prayer and leading the prayer",
            items = listOf(
                LearnItem(
                    id = "h_jumma", title = "Jumu'ah (Friday prayer)",
                    arabic = "", tamilTransliteration = "", englishTransliteration = "",
                    meaningTamil = "ஜும்ஆ: இமாம் இரண்டு குத்பாக்களை (உரைகள்) நிகழ்த்துவார். குத்பாவின் போது அமைதியாக கேட்கவும். பின்னர் 2 ரக்அத் ஜும்ஆ ஃபர்ள் ஜமாஅத்தாகத் தொழுகவும். ஹனஃபி முறையில் ஜும்ஆவுக்கு முன்னும் பின்னும் சுன்னத் தொழுகைகள் உண்டு.",
                    meaningEnglish = "Jumu'ah: the imam gives two khutbahs (sermons). Listen quietly during the khutbah. Then 2 rakats of the Friday fard are prayed in congregation. In Hanafi practice there are sunnah prayers before and after.",
                ),
                LearnItem(
                    id = "h_lead", title = "Leading the five prayers (imam)",
                    arabic = "", tamilTransliteration = "", englishTransliteration = "",
                    meaningTamil = "இமாம்: நிய்யத் செய்து தக்பீர் கூறி ஜமாஅத்தை நடத்தவும். ஃபஜ்ர், மஃக்ரிப், இஷாவின் முதல் இரண்டு ரக்அத்களில் சத்தமாக ஓதவும். ஹனஃபி முறையில் பிஸ்மில்லாவும் ஆமீனும் மெதுவாக ஓதப்படும். பின்தொடர்பவர்கள் இமாமைப் பின்பற்றவும்.",
                    meaningEnglish = "Imam: make the intention, say the takbir, and lead the congregation. Recite aloud in Fajr, Maghrib, and the first two rakats of Isha. In Hanafi practice, 'Bismillah' and 'Ameen' are said silently. The congregation follows the imam.",
                ),
            ),
        ),
        LearnCategory(
            title = "Shafi'i: differences from Hanafi",
            items = listOf(
                LearnItem(
                    id = "s_prayer", title = "Shafi'i prayer: main differences",
                    arabic = "", tamilTransliteration = "", englishTransliteration = "",
                    meaningTamil = "ஷாஃபிஈ முறை: தக்பீர் தஹ்ரீமா, ருகூஃவுக்கு முன், ருகூஃவிலிருந்து எழும்போது கைகளை உயர்த்தவும். கைகளை மார்பின் மீது கட்டவும். சத்தமாக ஓதும் தொழுகைகளில் பிஸ்மில்லாவையும் ஆமீனையும் சத்தமாகச் சொல்லவும்.",
                    meaningEnglish = "Shafi'i: raise the hands at the opening takbir, before bowing, and when rising from bowing. Place the hands on the chest. In prayers read aloud, say 'Bismillah' and 'Ameen' aloud.",
                ),
                LearnItem(
                    id = "s_qunoot", title = "Shafi'i Qunoot (in Fajr, after rising from bowing)",
                    arabic = "اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَعَافِنِي فِيمَنْ عَافَيْتَ، وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لِي فِيمَا أَعْطَيْتَ، وَقِنِي شَرَّ مَا قَضَيْتَ، فَإِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، إِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ، تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ",
                    tamilTransliteration = "அல்லாஹும்மஹ்தினீ ஃபீமன் ஹதைத். வ ஆஃபினீ ஃபீமன் ஆஃபைத். வ தவல்லனீ ஃபீமன் தவல்லைத். வ பாரிக் லீ ஃபீமா அஃதைத். வ கினீ ஷர்ர மா கழைத். ஃபஇன்னக்க தக்ழீ வலா யுக்ழா அலைக். இன்னஹு லா யதில்லு மன் வாலைத், வலா யஇஸ்ஸு மன் ஆதைத். தபாரக்த ரப்பனா வ தஆலைத்.",
                    englishTransliteration = "Allahummahdinee feeman hadayt, wa 'aafinee feeman 'aafayt, wa tawallanee feeman tawallayt, wa baarik lee feemaa a'tayt, wa qinee sharra maa qadayt. Fa innaka taqdee wa laa yuqdaa 'alayk. Innahu laa yadhillu man waalayt, wa laa ya'izzu man 'aadayt. Tabaarakta Rabbanaa wa ta'aalayt.",
                    meaningTamil = "இறைவா! நீ நேர்வழி காட்டியவர்களுடன் என்னையும் நேர்வழி காட்டு. நீ பாதுகாத்தவர்களுடன் என்னையும் பாதுகாத்தருள்வாயாக. நீ விதித்த தீமையிலிருந்து என்னைக் காப்பாயாக. நீயே தீர்ப்பளிப்பவன்; உன் மீது எவரும் தீர்ப்பளிக்க முடியாது. எங்கள் இறைவா! நீ மிகப் பாக்கியமுடையவன், உயர்ந்தவன்.",
                    meaningEnglish = "O Allah, guide me among those You have guided, grant me well-being among those You have granted well-being, befriend me among those You have befriended, bless me in what You have given, and protect me from the evil of what You have decreed. You decree, and none can decree over You. Blessed are You, our Lord, and exalted. (Shafi'i recites this in Fajr. Hanafi uses a different qunoot in Witr.)",
                ),
                LearnItem(
                    id = "s_janaza", title = "Shafi'i janaza: main differences",
                    arabic = "", tamilTransliteration = "", englishTransliteration = "",
                    meaningTamil = "ஷாஃபிஈ ஜனாசா: 4 தக்பீர். முதல் தக்பீருக்குப் பின் சூரா ஃபாத்திஹா ஓதவும். இரண்டாம் தக்பீருக்குப் பின் ஸலவாத். மூன்றாம் தக்பீருக்குப் பின் இறந்தவருக்காக துஆ. நான்காம் தக்பீருக்குப் பின் துஆ, பின் ஸலாம். (ஷாஃபிஈ முறையில் ஒவ்வொரு தக்பீரிலும் கைகளை உயர்த்தவும். இது ஹனஃபி முறையிலிருந்து வேறுபடுகிறது.)",
                    meaningEnglish = "Shafi'i janaza: 4 takbirs. After the first, recite Al-Fatiha. After the second, send blessings on the Prophet. After the third, pray for the deceased. After the fourth, pray, then give salam. (Shafi'i raises the hands at each takbir, which differs from Hanafi.)",
                ),
                LearnItem(
                    id = "s_note", title = "Note on these differences",
                    arabic = "", tamilTransliteration = "", englishTransliteration = "",
                    meaningTamil = "இவை இரு மத்ஹபுகளின் முக்கிய வேறுபாடுகள். விவரங்கள் வேறுபடலாம். உங்கள் குழுவின் இமாம் அல்லது ஆலிம் உறுதிப்படுத்திய முறையைப் பின்பற்றவும்.",
                    meaningEnglish = "These are the main differences between the two schools. Details can vary. Follow the method confirmed by your group's imam or scholar.",
                ),
